const i=[{id:"C01",title:"OMS · Le stress : questions et réponses",url:"https://www.who.int/news-room/questions-and-answers/item/stress",type:"guidance",finding:"Décrit le stress comme de l’inquiétude ou une tension mentale face à une situation difficile. Propose des habitudes régulières, du repos, une activité adaptée, des liens de confiance et une exposition maîtrisée aux actualités.",limitation:"Conseils au grand public, sans mesure d’un effet d’ODA. Ils doivent convenir à chacun ; ils ne suppriment pas toutes les causes de stress et ne remplacent pas les soins."},{id:"C02",title:"NHS · Trouver de l’aide face au stress",url:"https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/feelings-and-symptoms/stress/",type:"guidance",finding:"Le stress peut s’accompagner de signes physiques, cognitifs, émotionnels et comportementaux. Consulter quand il devient difficile de faire face ou que les démarches personnelles ne suffisent pas.",limitation:"Des tensions, des maux de tête ou des difficultés de concentration ne révèlent pas leur cause. Des symptômes nouveaux ou inquiétants peuvent nécessiter un avis médical. Les nommer ne constitue pas un diagnostic."},{id:"C03",title:"NHS Every Mind Matters · L’anxiété",url:"https://www.nhs.uk/every-mind-matters/mental-health-issues/anxiety/",type:"guidance",finding:"Propose d’aborder progressivement des situations redoutées mais sûres, de noter les déclencheurs et de consulter si l’anxiété gêne le quotidien. Un essoufflement peut avoir une autre cause.",limitation:"Ces conseils ne garantissent pas que chaque situation redoutée soit sûre. Ils ne valident pas ODA comme thérapie d’exposition. Quitter une situation de violence ou de danger réel protège la personne."},{id:"C04",title:"NHS · Le trouble panique",url:"https://www.nhs.uk/mental-health/conditions/panic-disorder/",type:"guidance",finding:"Des crises de panique répétées nécessitent une évaluation professionnelle. D’autres affections peuvent provoquer des symptômes physiques similaires. Les traitements peuvent inclure une TCC et des médicaments prescrits.",limitation:"Une douleur thoracique, une sensation de malaise ou un essoufflement nouveaux n’indiquent pas automatiquement une panique sans danger. La respiration seule ne traite pas le trouble panique. Les décisions médicamenteuses se prennent avec le prescripteur."},{id:"C05",title:"NHS · 2026 · Exercices de respiration contre le stress",url:"https://www.nhs.uk/mental-health/self-help/guides-tools-and-activities/breathing-exercises-for-stress/",type:"guidance",finding:"Propose de respirer doucement, sans forcer, dans une position confortable avec des appuis, et de pratiquer régulièrement. Compter reste facultatif et ne doit pas demander d’effort.",limitation:"Ces conseils ne donnent ni effet mesuré isolément, ni rythme optimal, ni garantie. Cette respiration douce diffère du protocole étudié à double inspiration. Les pauses plus courtes d’ODA sont des adaptations."},{id:"C06",title:"NHS · 10 pistes pour gérer le stress",url:"https://www.nhs.uk/mental-health/self-help/guides-tools-and-activities/tips-to-reduce-stress/",type:"guidance",finding:"Une activité adaptée et des liens de confiance peuvent aider à faire face. Une émotion moins intense ne signifie pas que la situation stressante a disparu.",limitation:"Conseils, sans preuve chiffrée d’un effet isolé. Aider les autres peut ne pas convenir quand on est déjà débordé. Lister des contacts sans les solliciter ne prouve pas qu’on a reçu du soutien."},{id:"C07",title:"Singh et al. · 2023 · Synthèse des revues sur l’activité physique",url:"https://www.newswise.com/pdf_docs/167719499939215_Singh%20et%20al%202023.pdf",type:"research",finding:"97 revues couvraient 1 039 essais distincts. Dépression : différence moyenne standardisée médiane −0,43 (intervalle interquartile −0,66 à −0,27) ; anxiété : −0,42 (−0,66 à −0,26). Détresse : −0,60 (IC à 95 % −0,78 à −0,42), d’après une revue de six essais.",limitation:"77 revues étaient de qualité extrêmement faible. Les effectifs rapportés se recoupent. Médianes et intervalles interquartiles ne sont ni effets regroupés ni intervalles de confiance. Les associations entre sous-groupes, intensité et durée ne prescrivent aucune dose personnelle et ne prédisent pas l’effet d’une marche."},{id:"C08",title:"Fincham et al. · 2023 · Méta-analyse des essais de respiration",url:"https://doi.org/10.1038/s41598-022-27247-y",type:"research",finding:"L’analyse principale du stress regroupait 12 essais randomisés auprès de 785 adultes : g de Hedges −0,35 (IC à 95 % −0,55 à −0,14). Techniques et populations variaient.",limitation:"Un risque de biais modéré et un suivi limité réduisent la confiance. Les sous-groupes n’établissent ni supériorité de la respiration lente, ni protocole optimal, ni équivalence avec un traitement, ni sécurité identique des techniques rapides et lentes."},{id:"C09",title:"Webb, Miles et Sheeran · 2012 · Méta-analyse de la régulation des émotions",url:"https://pubmed.ncbi.nlm.nih.gov/22582737/",type:"research",finding:"306 comparaisons expérimentales trouvaient en moyenne : changement de perspective d+ 0,45 ; réinterprétation de la situation 0,36 ; suppression des pensées −0,12.",limitation:"Résumé consulté ; surtout des émotions provoquées brièvement en laboratoire. Écarter une pensée diffère de retenir son expression. Cela ne montre ni un échec systématique de la suppression, ni la vérité d’une interprétation rassurante, ni un bénéfice durable des questions d’ODA."},{id:"C10",title:"NHS Every Mind Matters · Revoir les pensées qui ne t’aident pas",url:"https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/",type:"guidance",finding:"Propose de repérer une pensée, d’examiner les faits et d’envisager une lecture plus équilibrée. Face à de vraies difficultés, il peut falloir résoudre un problème, accepter une réalité ou demander du soutien.",limitation:"Conseils, sans essai de la fiche abrégée d’ODA. Une lecture équilibrée peut laisser place à l’incertitude. Les interprétations positives doivent s’appuyer sur des faits et ne pas minimiser les mauvais traitements."},{id:"C11",title:"Balban et al. · 2023 · Essai de respiration structurée",url:"https://doi.org/10.1016/j.xcrm.2022.100895",type:"research",finding:"108 adultes répartis au hasard pratiquaient respiration ou pleine conscience cinq minutes par jour durant 28 jours. Gain moyen d’affect positif, respirations regroupées : 1,91 point contre 1,22. Le modèle favorisait le soupir cyclique face à la pleine conscience. L’anxiété diminuait sans différence significative entre groupes.",limitation:"Petits groupes, exclusions médicales et psychiatriques, enregistrement rétrospectif ; aucun intervalle de confiance entre groupes vérifié. Ni deux respirations, ni classement universel, ni mécanisme causal prouvé. Amélioration significative du sommeil ou de la variabilité de la fréquence cardiaque non établie ; bénéfice durable contre l’anxiété non testé pour cette pause ODA."},{id:"C13",title:"Torre et Lieberman · 2018 · Revue sur les émotions mises en mots",url:"https://journals.sagepub.com/doi/abs/10.1177/1754073917742706",type:"research",finding:"Cette revue narrative examine les liens entre mettre ses émotions en mots et plusieurs mesures des réactions émotionnelles. Les nommer constitue un essai plausible.",limitation:"Résumé et références consultés. Aucun effectif regroupé ni effet chiffré vérifiés. Un mot ne garantit pas de soulagement ressenti et ne résout pas la cause du stress. L’exercice ODA associant situation et émotion est une adaptation."},{id:"C14",title:"Kross et al. · 2014 · Se parler avec du recul",url:"https://doi.org/10.1037/a0035173",type:"research",finding:"Sept études réunissaient 585 participants. Dans une interaction sociale structurée, réfléchir sans employer la première personne améliorait la performance évaluée par des observateurs, sans réduire davantage l’anxiété avant l’échange.",limitation:"Stress social en laboratoire, sans traitement d’un trouble anxieux ni preuve d’un calme immédiat. Préenregistrement et reproduction exacte indépendante non vérifiés. Les gestes ajoutés par ODA dans un contexte professionnel n’ont pas été testés."},{id:"C17",title:"Edwards et Loprinzi · 2018 · Essai de marche brève et de méditation",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC6064756/",type:"research",finding:"66 jeunes adultes répartis au hasard faisaient dix minutes de marche sur tapis, de méditation guidée ou de repos assis. Les interactions sur la fatigue et l’humeur globale concernaient les trois groupes. Pour la marche, le changement d’humeur globale dans le groupe avait p = 0,10.",limitation:"Petit essai ponctuel ; ni intervalles de confiance des effets ni reproduction exacte indépendante vérifiés. Les résultats n’établissent clairement ni amélioration globale de l’humeur par la marche, ni bénéfice d’une autre forme de mouvement accessible."},{id:"C12",title:"Zaccaro et al. · 2018 · Revue de la physiologie de la respiration lente",url:"https://www.frontiersin.org/journals/human-neuroscience/articles/10.3389/fnhum.2018.00353/full",type:"research",finding:"Synthèse qualitative de 15 études chez des participants en bonne santé : la respiration lente était associée à des mesures physiologiques et psychologiques. Aucun effet regroupé n’était estimé.",limitation:"Petites études hétérogènes chez les mêmes personnes ou avant/après, sans suivi longitudinal randomisé. Ces associations ne prouvent ni mécanisme de santé mentale lié au nerf vague, ni fréquence optimale, ni traitement des troubles anxieux."},{id:"cyclic-sighing",title:"Balban et al. · 2023 · Essai de respiration structurée",url:"https://doi.org/10.1016/j.xcrm.2022.100895",type:"research",finding:"108 adultes répartis au hasard pratiquaient respiration ou pleine conscience cinq minutes par jour durant 28 jours. Gain moyen d’affect positif, respirations regroupées : 1,91 point contre 1,22. Le modèle favorisait le soupir cyclique face à la pleine conscience. L’anxiété diminuait sans différence significative entre groupes.",limitation:"Petits groupes, exclusions médicales et psychiatriques, enregistrement rétrospectif ; aucun intervalle de confiance entre groupes vérifié. Ni deux respirations, ni classement universel, ni mécanisme causal prouvé. Amélioration significative du sommeil ou de la variabilité de la fréquence cardiaque non établie ; bénéfice durable contre l’anxiété non testé pour cette pause ODA."},{id:"slow-breathing",title:"Zaccaro et al. · 2018 · Revue de la physiologie de la respiration lente",url:"https://www.frontiersin.org/journals/human-neuroscience/articles/10.3389/fnhum.2018.00353/full",type:"research",finding:"Synthèse qualitative de 15 études chez des participants en bonne santé : la respiration lente était associée à des mesures physiologiques et psychologiques. Aucun effet regroupé n’était estimé.",limitation:"Petites études hétérogènes chez les mêmes personnes ou avant/après, sans suivi longitudinal randomisé. Ces associations ne prouvent ni mécanisme de santé mentale lié au nerf vague, ni fréquence optimale, ni traitement des troubles anxieux."},{id:"activity-mood",title:"Singh et al. · 2023 · Synthèse des revues sur l’activité physique",url:"https://www.newswise.com/pdf_docs/167719499939215_Singh%20et%20al%202023.pdf",type:"research",finding:"97 revues couvraient 1 039 essais distincts. Dépression : différence moyenne standardisée médiane −0,43 (intervalle interquartile −0,66 à −0,27) ; anxiété : −0,42 (−0,66 à −0,26). Détresse : −0,60 (IC à 95 % −0,78 à −0,42), d’après une revue de six essais.",limitation:"77 revues étaient de qualité extrêmement faible. Les effectifs rapportés se recoupent. Médianes et intervalles interquartiles ne sont ni effets regroupés ni intervalles de confiance. Les associations entre sous-groupes, intensité et durée ne prescrivent aucune dose personnelle et ne prédisent pas l’effet d’une marche."},{id:"emotion-regulation",title:"Webb, Miles et Sheeran · 2012 · Méta-analyse de la régulation des émotions",url:"https://pubmed.ncbi.nlm.nih.gov/22582737/",type:"research",finding:"306 comparaisons expérimentales trouvaient en moyenne : changement de perspective d+ 0,45 ; réinterprétation de la situation 0,36 ; suppression des pensées −0,12.",limitation:"Résumé consulté ; surtout des émotions provoquées brièvement en laboratoire. Écarter une pensée diffère de retenir son expression. Cela ne montre ni un échec systématique de la suppression, ni la vérité d’une interprétation rassurante, ni un bénéfice durable des questions d’ODA."},{id:"affect-labeling",title:"Torre et Lieberman · 2018 · Revue sur les émotions mises en mots",url:"https://journals.sagepub.com/doi/abs/10.1177/1754073917742706",type:"research",finding:"Cette revue narrative examine les liens entre mettre ses émotions en mots et plusieurs mesures des réactions émotionnelles. Les nommer constitue un essai plausible.",limitation:"Résumé et références consultés. Aucun effectif regroupé ni effet chiffré vérifiés. Un mot ne garantit pas de soulagement ressenti et ne résout pas la cause du stress. L’exercice ODA associant situation et émotion est une adaptation."},{id:"who-stress",title:"OMS · Le stress : questions et réponses",url:"https://www.who.int/news-room/questions-and-answers/item/stress",type:"guidance",finding:"Décrit le stress comme de l’inquiétude ou une tension mentale face à une situation difficile. Propose des habitudes régulières, du repos, une activité adaptée, des liens de confiance et une exposition maîtrisée aux actualités.",limitation:"Conseils au grand public, sans mesure d’un effet d’ODA. Ils doivent convenir à chacun ; ils ne suppriment pas toutes les causes de stress et ne remplacent pas les soins."},{id:"nhs-stress",title:"NHS · Trouver de l’aide face au stress",url:"https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/feelings-and-symptoms/stress/",type:"guidance",finding:"Le stress peut s’accompagner de signes physiques, cognitifs, émotionnels et comportementaux. Consulter quand il devient difficile de faire face ou que les démarches personnelles ne suffisent pas.",limitation:"Des tensions, des maux de tête ou des difficultés de concentration ne révèlent pas leur cause. Des symptômes nouveaux ou inquiétants peuvent nécessiter un avis médical. Les nommer ne constitue pas un diagnostic."},{id:"nhs-stress-tips",title:"NHS · 10 pistes pour gérer le stress",url:"https://www.nhs.uk/mental-health/self-help/guides-tools-and-activities/tips-to-reduce-stress/",type:"guidance",finding:"Une activité adaptée et des liens de confiance peuvent aider à faire face. Une émotion moins intense ne signifie pas que la situation stressante a disparu.",limitation:"Conseils, sans preuve chiffrée d’un effet isolé. Aider les autres peut ne pas convenir quand on est déjà débordé. Lister des contacts sans les solliciter ne prouve pas qu’on a reçu du soutien."},{id:"calm-nhs-anxiety",title:"NHS Every Mind Matters · L’anxiété",url:"https://www.nhs.uk/every-mind-matters/mental-health-issues/anxiety/",type:"guidance",finding:"Propose d’aborder progressivement des situations redoutées mais sûres, de noter les déclencheurs et de consulter si l’anxiété gêne le quotidien. Un essoufflement peut avoir une autre cause.",limitation:"Ces conseils ne garantissent pas que chaque situation redoutée soit sûre. Ils ne valident pas ODA comme thérapie d’exposition. Quitter une situation de violence ou de danger réel protège la personne."}],n=[{schemaVersion:2,revision:2,id:"calm-1",courseId:"calm",locale:"fr",title:"Retiens la réponse que tu pourrais regretter",goal:"Repère un moment de stress familier et choisis un geste sûr et utile avant de répondre.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Mâchoire serrée, réponse déjà tapée. Choisis la suite avant d’appuyer sur envoyer.",reason:{id:"calm-1-reason",label:"Que te coûte ta réaction habituelle au stress ?",kind:"text",maxLength:160,optional:!0,suggestions:["Des réponses que je regrette","Des priorités toujours floues","La tension du travail ramenée chez moi","Aucune occasion passée"]},why:{id:"calm-1-why",label:"Que protège ce geste dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Tensions, maux de tête et concentration difficile peuvent accompagner le stress, sans en révéler la cause. Un signal familier t’invite à choisir la suite, sans poser de diagnostic. Des symptômes physiques nouveaux ou inquiétants nécessitent un avis médical.","Nomme l’émotion et la situation : « Cette échéance m’inquiète. » C’est un essai raisonnable, sans garantie de soulagement. Puis fais quelque chose d’utile : retiens une réponse impulsive, demande quelle tâche passe en premier, pose une limite sûre ou sollicite du soutien. Garde ce déclencheur et ce geste pour tes essais au fil du cours. Tu n’as pas à te sentir plus calme."],example:{title:"Camille change sa réponse",text:"À son bureau, Camille découvre une échéance encore modifiée. Sa mâchoire se serre comme souvent ; elle veut répondre sèchement. Elle se dit « la charge de travail m’inquiète », puis demande quelle tâche passe en premier. À midi, sa responsable n’a pas répondu. Camille note sa question et l’absence de réponse. Elle reste inquiète."}},move:{invitation:"Garde ton geste ; adapte cet exemple d’échéance.",instructions:["Repère le moment sans en diagnostiquer la cause.","Choisis une question, une pause, une limite ou une demande de soutien sûre."],prompts:[],suggestions:{action:["Demander quelle échéance passe en premier","Retenir une réponse impulsive","Décrire la charge sans remarque sèche"],minimum:["Envoyer une question citant les deux échéances","Garder une réponse en brouillon une minute","Envoyer une phrase factuelle sur la charge"],cue:["À réception d’un mail modifiant une échéance","Quand mon signal familier apparaît","Avant d’envoyer une réponse sèche"],place:["À mon bureau, dans le fil du mail","Un lieu sûr où faire une pause privée","Mon espace de communication accessible"],minutes:[2,1,5],fallback:["Garder le brouillon ; envoyer la question de priorité","Choisir une limite qui me protège","Demander du soutien à une personne disponible"],observation:["Question envoyée ; réponse ou silence","L’impulsion a-t-elle mené à un envoi ?","Le signal apparu et le geste choisi"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Demander quelle échéance passe en premier",minimum:"Envoyer une question citant les deux échéances",minutes:2,cueHint:"À réception d’un mail modifiant une échéance",placeHint:"À mon bureau, dans le fil du mail",obstacleHint:"Je commence à rédiger une réponse sèche",fallbackHint:"Garder le brouillon ; envoyer la question de priorité",observationHint:"Question envoyée ; réponse ou silence"},stopRule:"Des symptômes nouveaux ou inquiétants nécessitent un avis médical. Protège-toi ou demande du soutien si la situation est dangereuse.",accessibleAlternative:"Utilise un repère extérieur, l’écrit ou une aide à la communication. Pour demander du soutien, choisis « Adapter ce geste », puis « Soutien » ; précise ton minimum."},result:{question:"As-tu fait le geste choisi ?",observationPrompt:"Qu’as-tu fait après le signal familier, et que s’est-il réellement passé ensuite ?"},judgment:{primary:{id:"calm-1-decision",scenario:"Camille reçoit une échéance modifiée. Elle est en sécurité, mais veut répondre sèchement avant de clarifier les priorités.",question:"Quel geste utilise bien ce signal ?",options:[{id:"calm-1-full-explanation",text:"Envoyer aussitôt une explication détaillée de la charge, puis faire une pause avant de lire la réponse.",feedback:"Expliquer la charge peut aider. Mais un long message impulsif risque de manquer la décision dont Camille a besoin. Elle peut commencer par une question claire, sans considérer l’échéance comme réglée."},{id:"calm-1-name-only",text:"Nommer son inquiétude en privé et laisser la charge inchangée jusqu’à se sentir prête à en parler.",feedback:"Nommer l’émotion décrit le moment, sans fixer les priorités ni demander quoi que ce soit. Camille peut rester inquiète et poser une question sûre qui concerne le vrai problème de travail."},{id:"calm-1-priority-question",text:"Nommer son inquiétude, retenir la réponse sèche et demander quelle tâche doit passer en premier.",feedback:"Repérer le signal mène ici à un geste utile. La responsable peut tarder à répondre. Camille note sa demande et choisit une autre solution, sans prendre le silence pour un accord."}],bestOptionId:"calm-1-priority-question"}},carry:{takeaway:"Nomme le moment, puis choisis un geste dont tu observeras la suite.",followUp:{questionId:"calm-1-return",question:"Ton signal familier t’a-t-il amené à faire le geste choisi ?",observationPrompt:"Que s’est-il passé quand ton déclencheur s’est présenté ?",adjustmentPrompt:"Que veux-tu reprendre, changer ou faire avec de l’aide ?"}},goDeeper:{sections:[{heading:"Les signaux servent de repères, pas de diagnostics",paragraphs:["Le NHS décrit des signes physiques, cognitifs, émotionnels et comportementaux pouvant accompagner le stress [C02]. Une mâchoire habituellement serrée, de l’irritabilité ou une attention dispersée peuvent attirer ton attention. Ils ne prouvent toujours pas que le stress en soit la cause. D’autres explications sont possibles. Des symptômes nouveaux ou inquiétants ne doivent pas être écartés comme une tension ordinaire. Nommer un moment familier t’aide à choisir la suite ; ce n’est pas un diagnostic.","Ce cours te propose un déclencheur reconnaissable. Il ne te demande pas de scruter ton corps jusqu’à trouver un problème. Tu peux choisir un repère extérieur : ouvrir un mail difficile, les yeux ouverts, avec ton moyen de communication habituel. Ce moment permet de choisir une question, une pause, une limite ou une demande de soutien sûre. C’est une adaptation de planification proposée par ODA. Elle ne prouve ni que chacun présente des symptômes stables, ni que les repérer améliore à lui seul la santé."]},{heading:"Nommer l’émotion ne suffit pas",paragraphs:["La revue narrative de Torre et Lieberman examine la mise en mots des émotions et ses liens avec plusieurs mesures des réactions émotionnelles [C13]. Le résumé et les références consultés ne donnaient ni effectif total regroupé ni estimation chiffrée d’efficacité. Le soulagement ressenti n’est pas garanti. Associer un mot à une situation est une adaptation d’ODA, pas la reproduction exacte d’un traitement ou d’une procédure qui remettrait le cerveau à zéro.","Les conseils du NHS invitent à distinguer sa réaction du prochain geste choisi à partir des faits [C10]. « La charge de travail m’inquiète » peut correspondre à un vrai problème de charge. Il te faut peut-être des priorités claires, une aide pratique ou une protection plutôt qu’une histoire rassurante. Tes essais gardent trace de la suite, même d’une question sans réponse. Les leçons suivantes proposent un outil si un obstacle observé le rend utile. Tu peux demander du soutien dès maintenant, sans attendre de maîtriser tous les outils."]}],sourceIds:["C02","C13","C10"]}},{schemaVersion:2,revision:2,id:"calm-2",courseId:"calm",locale:"fr",title:"Pas besoin d’un calme parfait pour agir",goal:"Essaie une pause assise confortable, puis reprends ton geste sûr.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Discussion encore repoussée en attendant le calme ? Choisis une pause confortable, puis agis.",reason:{id:"calm-2-reason",label:"Quel geste repousses-tu en attendant de te sentir prêt ?",kind:"text",maxLength:160,optional:!0,suggestions:["Demander quelle échéance passe en premier","Dire non à un créneau de travail supplémentaire","Demander de l’aide pour organiser des soins","Aucun geste que je repousse"]},why:{id:"calm-2-why",label:"Que protège ce geste dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Une étude auprès de 108 adultes testait cinq minutes par jour pendant 28 jours, pas deux respirations. L’anxiété diminuait avec la respiration et la pleine conscience, sans différence significative entre groupes. Aucune méthode rapide n’est donc désignée comme solution universelle.","Si une pause aide ton geste prévu, assieds-toi en sécurité, les yeux ouverts. Respirer doucement sans forcer reste facultatif. Tu peux regarder un objet en respirant normalement. Arrête si tu te sens mal. Choisis ensuite un geste sûr, sans attendre le calme. Une pause courte n’hérite pas de l’effet étudié."],example:{title:"Camille arrête l’exercice",text:"Chez elle, Camille essaie de respirer doucement, assise, avant de parler de la charge du lendemain. Elle a la tête qui tourne, arrête aussitôt et respire normalement sans se lever. Une fois rétablie, elle envoie sa question sur les priorités. Elle note séparément l’arrêt et la question. La prochaine fois, elle regardera un objet : cette pause n’était pas assez confortable."}},move:{invitation:"Garde ton geste ; adapte l’échéance.",instructions:["Assieds-toi en sécurité : respire normalement avec un repère extérieur, ou doucement sans forcer.","Arrête si tu te sens mal. Au moment adapté, fais ton geste en sécurité."],prompts:[],suggestions:{action:["Faire une pause ; demander la priorité","Regarder un objet ; demander la priorité","Envoyer la question de priorité sans pause"],minimum:["Envoyer une question citant les deux échéances","Envoyer une phrase posant une limite claire","Envoyer la question de priorité sans exercice respiratoire"],cue:["Avant de répondre à une échéance modifiée","À réception d’un mail modifiant une échéance","Avant de répondre pour un créneau supplémentaire"],place:["Chez moi, avec des appuis et mon téléphone","À mon bureau, dans le fil du mail","Un endroit où rester assis, les yeux ouverts"],minutes:[2,1,5],fallback:["Finir la pause ; envoyer la question de priorité","Sans exercice, demander de l’aide pour la charge","Arrêter ; rester assis jusqu’à disparition des symptômes"],observation:["Confort de la pause ; question, réponse ou silence","Ai-je fait le geste choisi ?","Toute gêne et le geste réellement fait"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Faire une pause ; demander la priorité",minimum:"Envoyer une question citant les deux échéances",minutes:2,cueHint:"Avant de répondre à une échéance modifiée",placeHint:"Chez moi, avec des appuis et mon téléphone",obstacleHint:"Après une pause confortable, je vérifie encore si je suis calme",fallbackHint:"Finir la pause ; envoyer la question de priorité",observationHint:"Confort de la pause ; question, réponse ou silence"},stopRule:"Arrête si tu as des vertiges ou te sens mal ; reste assis et respire normalement. Symptômes nouveaux ou inquiétants : consulte. Douleur thoracique ou essoufflement sévères : soins urgents.",accessibleAlternative:"Les yeux ouverts et un repère extérieur conviennent. Ne bloque ni ne force ta respiration. Ne conduis pas avec des symptômes."},result:{question:"As-tu fait le geste choisi en sécurité ?",observationPrompt:"Quelle pause ou quel arrêt a eu lieu ? As-tu ensuite agi ?"},judgment:{primary:{id:"calm-2-decision",scenario:"Camille a la tête qui tourne pendant l’exercice respiratoire chez elle. Elle veut le terminer avant d’envoyer sa question préparée.",question:"Que demande la consigne d’arrêt ?",options:[{id:"calm-2-restart-later",text:"Attendre que la sensation passe, puis reprendre l’exercice prévu avant d’envoyer sa question.",feedback:"Reprendre fait de la durée prévue une obligation malgré la gêne. Camille doit arrêter, respirer normalement en sécurité et faire évaluer ses symptômes si nécessaire. Elle n’a pas à gagner le droit de poser sa question."},{id:"calm-2-stop-normal",text:"Arrêter, respirer normalement en restant assise en sécurité et consulter si les symptômes persistent ou inquiètent.",feedback:"La sécurité passe avant la fin d’un exercice. Camille pourra choisir un repère extérieur ou ne pas pratiquer. Des symptômes nouveaux ou inquiétants ne doivent pas être attribués d’office au stress."},{id:"calm-2-gentler-finish",text:"Réduire l’effort, finir avec des respirations plus douces, puis décider de changer de méthode demain.",feedback:"Respirer plus doucement peut sembler une adaptation. Mais poursuivre avec la tête qui tourne contredit la consigne d’arrêt. Arrête maintenant, reste assis en sécurité et respire normalement au lieu de finir."}],bestOptionId:"calm-2-stop-normal"}},carry:{takeaway:"Un outil utile respecte tes limites et te laisse choisir la suite.",followUp:{questionId:"calm-2-return",question:"La pause était-elle confortable ? A-t-elle aidé ton geste ou l’a-t-elle retardé ?",observationPrompt:"Que s’est-il passé quand ton déclencheur s’est présenté ?",adjustmentPrompt:"Que veux-tu reprendre, changer ou faire avec de l’aide ?"}},goDeeper:{sections:[{heading:"L’essai ne prouve pas un effet immédiat",paragraphs:["Balban et ses collègues ont réparti au hasard 108 adultes en petits groupes : cinq minutes par jour pendant 28 jours [C11]. Les groupes de respiration regroupés gagnaient en moyenne 1,91 point d’affect positif par jour, contre 1,22 pour la pleine conscience. Un modèle statistique favorisait le soupir cyclique face à la pleine conscience. Ces moyennes brutes regroupées ne donnent pas la moyenne du seul soupir cyclique et ne prouvent aucun classement universel. L’anxiété diminuait sans différence significative entre les groupes.","L’essai exploratoire avait des exclusions médicales et psychiatriques ; son enregistrement était rétrospectif. Il n’établissait aucune amélioration significative du sommeil ou de la variabilité de la fréquence cardiaque. Il ne prouvait ni mécanisme lié au nerf vague ni bénéfice de deux respirations. Ses résultats n’établissent pas de bénéfice durable contre l’anxiété pour cette pause plus courte. Ici, tu choisis une pause confortable et volontaire, sans prescription du protocole à double inspiration. L’équivalence de cette pause courte avec le protocole original n’a pas été testée."]},{heading:"Le confort fait partie du choix",paragraphs:["Les conseils respiratoires du NHS insistent sur une position confortable avec des appuis et une respiration douce, sans forcer [C05]. Compter est facultatif ; aucun rapport précis entre inspiration et expiration n’est nécessaire. Ce sont des conseils pratiques, pas une durée isolée évaluée par essai randomisé. Il ne s’agit pas ici de respirer plus profondément, plus vite ou avec plus d’effort. Tu peux garder les yeux ouverts, respirer normalement et regarder un objet familier.","Le NHS rappelle que des sensations physiques évoquant une panique peuvent accompagner d’autres affections [C04]. Arrête l’exercice si tu as des vertiges ou te sens mal. Reste assis en sécurité et respire normalement. Ne conduis pas avec des symptômes. S’ils persistent ou inquiètent, consulte ; s’ils sont sévères ou urgents, appelle les secours locaux. Des crises répétées ou un quotidien perturbé justifient aussi une aide professionnelle. Note un arrêt prudent, une pratique inconfortable et une question envoyée plus tard. Trois faits distincts, pas un échec à devenir calme."]}],sourceIds:["C04","C05","C11"]}},{schemaVersion:2,revision:2,id:"calm-3",courseId:"calm",locale:"fr",title:"Une pause sans séance de sport",goal:"Ajoute un mouvement bref adapté seulement s’il aide ton geste prévu aujourd’hui.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Pas de séance complète aujourd’hui ? Une petite pause peut aider avant le geste prévu.",reason:{id:"calm-3-reason",label:"Que t’a coûté une pause sautée ? Sans occasion récente, tu peux aussi répondre.",kind:"text",maxLength:160,optional:!0,suggestions:["J’ai continué à répondre dans la précipitation","La tension a suivi à la tâche suivante","Aucune pause sautée récemment"]},why:{id:"calm-3-why",label:"Que protège ce geste dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Les programmes d’activité physique peuvent réduire la détresse en moyenne, sans prédire l’effet d’une marche brève. Dans un petit essai de dix minutes, l’évolution globale de l’humeur après la marche n’était pas statistiquement claire. Sans meilleure humeur, la pause compte quand même.","Si bouger convient avant ton geste prévu, essaie une version confortable et accessible. Garde le déclencheur, puis reviens au geste. Bouger assis ou rester immobile peut te convenir, sans hériter de l’effet étudié sur la marche. Note la version et la durée réelle. Garde ton geste initial s’il fonctionne déjà."],example:{title:"Camille garde la petite version",text:"Camille prévoyait une marche avant de vérifier les priorités de l’après-midi. Pluie et livraison : elle n’a que deux minutes. Elle bouge confortablement sur sa chaise, puis envoie sa question préparée. Sa tension reste la même. Elle note la version, la durée et l’envoi. Demain, elle pourra garder cette organisation sans devoir rattraper des minutes."}},move:{invitation:"Garde ton geste ; adapte cet exemple de pause assise.",instructions:["Ajoute du mouvement seulement s’il répond à un obstacle dans ton essai prévu.","Pour commencer, bouge assis une minute avant d’envoyer ta question préparée sur les priorités.","Si bouger ne convient pas, garde la question seule dans « Action » et « Minimum »."],prompts:[],suggestions:{action:["Bouger assis ; demander la priorité","Marcher brièvement ; envoyer la question","Envoyer la question de priorité sans bouger"],minimum:["Bouger assis une minute ; envoyer la question","Une minute de marche ; envoyer la question","Envoyer une question citant les deux échéances"],cue:["Après déjeuner, avant de vérifier les priorités","Après ma pause déjeuner habituelle","À réception d’un mail modifiant une échéance"],place:["À mon bureau, assis avec des appuis","Ma chaise avec des appuis","Un trajet de marche familier et sûr"],minutes:[2,5,10],fallback:["Sans mouvement, envoyer la question de priorité","Garder le geste ; éviter le mouvement inadapté","Demander conseil pour un mouvement adapté"],observation:["Durée du mouvement ; question, réponse ou silence","Toute gêne pendant la pause","Des sensations inchangées comptent aussi"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Bouger assis ; demander la priorité",minimum:"Bouger assis une minute ; envoyer la question",minutes:2,cueHint:"Après déjeuner, avant de vérifier les priorités",placeHint:"À mon bureau, assis avec des appuis",obstacleHint:"Douleur, accès ou temps : bouger ne convient pas",fallbackHint:"Sans mouvement, envoyer la question de priorité",observationHint:"Durée du mouvement ; question, réponse ou silence"},stopRule:"Arrête de bouger en cas de douleur, vertiges ou malaise ; demande un avis adapté. Le mouvement ne sert pas de punition.",accessibleAlternative:"Bouge assis ou fais une pause immobile. Sans mouvement, garde la question seule dans « Action » et « Minimum »."},result:{question:"As-tu fait la pause et le geste choisis ?",observationPrompt:"Quelle version et quelle durée, puis qu’as-tu fait ensuite ?"},judgment:{primary:{id:"calm-3-decision",scenario:"Camille répond trop vite après avoir sauté ses pauses. Elle a deux minutes, une question préparée et peut bouger assise. La pluie empêche sa marche.",question:"Quel plan teste le mieux ce problème observé ?",options:[{id:"calm-3-larger-tomorrow",text:"Envoyer sa question maintenant et garder la marche pour une pause ultérieure, quand la météo le permettra.",feedback:"Envoyer maintenant clarifie vite les priorités ; une marche reste possible plus tard. Mais cela ne teste pas sa précipitation observée. Une minute adaptée trouve encore sa place avant la question préparée."},{id:"calm-3-research-first",text:"Comparer des mouvements pendant ces deux minutes, puis choisir un trajet avant de demander les priorités.",feedback:"Se renseigner peut aider quand aucune option adaptée n’est disponible. Camille en a déjà une. Comparer encore remplace la pause et la question par une préparation qui ne résout pas la contrainte du jour."},{id:"calm-3-suitable-small",text:"Bouger assise une minute, envoyer sa question préparée et noter la version sans exiger de soulagement.",feedback:"Ce choix respecte le temps disponible et garde le geste utile. Bouger assis est une adaptation, pas le protocole de marche étudié. Une tension inchangée reste une observation honnête."}],bestOptionId:"calm-3-suitable-small"}},carry:{takeaway:"Choisis la version qui convient. Une pause manquée ne devient pas une dette pour demain.",followUp:{questionId:"calm-3-return",question:"La pause convenait-elle à ton corps et laissait-elle du temps pour ton geste ?",observationPrompt:"Que s’est-il passé quand ton déclencheur s’est présenté ?",adjustmentPrompt:"Que veux-tu reprendre, changer ou faire avec de l’aide ?"}},goDeeper:{sections:[{heading:"Les moyennes ne prédisent pas une seule pause",paragraphs:["Singh et ses collègues ont synthétisé 97 revues couvrant 1 039 essais randomisés distincts [C07]. Pour la dépression et l’anxiété, les résultats étaient des effets standardisés médians entre revues, pas une estimation unique regroupant les participants. Dépression : −0,43, avec un intervalle interquartile de −0,66 à −0,27. Anxiété : −0,42, avec un intervalle de −0,66 à −0,26. Ces intervalles ne sont pas des intervalles de confiance. Les effectifs rapportés se recoupent.","L’estimation de détresse était −0,60, avec un intervalle de confiance à 95 % de −0,78 à −0,42. Elle provenait d’une revue de six essais. 77 revues étaient jugées de qualité extrêmement faible. Les associations avec l’intensité ou la durée ne prouvent pas que plus intense ou plus court soit préférable pour chacun. Ces données invitent à envisager une activité adaptée avec d’autres soutiens. Elles ne justifient ni d’allonger une pause de deux minutes ni de promettre une baisse de tension aujourd’hui."]},{heading:"Ce qu’un essai de marche brève peut t’apprendre",paragraphs:["Edwards et Loprinzi ont réparti au hasard 66 jeunes adultes entre dix minutes de marche sur tapis, de méditation guidée ou de repos assis [C17]. Les interactions sur la fatigue et l’humeur globale comparaient les trois groupes. Elles n’estimaient pas un effet propre à la marche. Dans le groupe marche, le changement d’humeur globale avait p = 0,10. Les résultats n’établissent pas clairement un bénéfice global sur l’humeur. Les intervalles de confiance des effets et une reproduction exacte indépendante n’ont pas été vérifiés.","Marcher à l’intérieur, choisir un rythme confortable, bouger assis ou faire une pause immobile sont des adaptations d’ODA, pas cette procédure de laboratoire. Le NHS présente le mouvement comme une possibilité pour faire face, sans suppression de la cause du stress [C06]. Tes notes servent à vérifier l’adéquation, l’accès et la réalisation du geste prévu ensuite. Un seul changement de ressenti avant/après ne prouve pas sa cause. Une maladie, une douleur ou des difficultés alimentaires peuvent demander un avis qualifié plutôt qu’un objectif d’activité accru."]}],sourceIds:["C06","C07","C17"]}},{schemaVersion:2,revision:2,id:"calm-4",courseId:"calm",locale:"fr",title:"« On peut parler ? » Vérifie ton scénario",goal:"Distingue les faits de tes prédictions, puis choisis un geste sûr et concret.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Un message vague, et tu imagines déjà la fin. Vérifie ce que tu sais avant d’agir.",reason:{id:"calm-4-reason",label:"Que repousses-tu parce qu’une prédiction te semble certaine ?",kind:"text",maxLength:160,optional:!0,suggestions:["Demander quoi préparer","Envoyer une correction déjà possible","Demander de l’aide face à un danger","Aucun geste que je repousse"]},why:{id:"calm-4-why",label:"Que protège ce geste dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Une pensée équilibrée n’est pas forcément positive. Le NHS conseille d’examiner les faits. « Je ne sais pas encore » peut être plus juste que « J’ai fait une bêtise » ou « On m’apprécie sûrement ». Aucune intention imaginée n’est un fait.","Reprends ton déclencheur et ton geste. Si une prédiction te bloque, repère ce qui a été dit ou fait. Clarifie, corrige, pose une limite ou demande du soutien en sécurité. Changer de regard ne supprime ni surcharge ni mauvais traitements. Essaie le geste et observe la suite, même si le doute reste."],example:{title:"Camille demande quoi préparer",text:"Camille reçoit « On peut parler demain ? » et imagine avoir créé un problème. Elle note le message exact, puis demande quoi préparer pour cet échange sans danger. Sa responsable répond : « Le planning modifié du client. » Camille a une tâche utile, sans connaître toute la suite. Elle prépare le planning et note l’échange. Elle reste nerveuse."}},move:{invitation:"Garde ton geste ; adapte cette question avant un rendez-vous.",instructions:["Sépare observation et prédiction.","Demande, corrige, protège-toi ou cherche du soutien, sans inventer les intentions de l’autre."],prompts:[],suggestions:{action:["Demander quoi préparer pour le rendez-vous","Clarifier une demande ambiguë","Corriger ou poser une limite en sécurité"],minimum:["Envoyer une question sur la préparation","Poser une question pour clarifier","Faire un geste choisi pour me protéger"],cue:["Quand un message de rendez-vous omet le sujet","À réception d’un mail professionnel difficile","Avant d’agir sur une prédiction"],place:["À mon bureau, dans le mail reçu","Un lieu privé, avec une aide pour communiquer","Mon espace accessible pour écrire et contacter"],minutes:[2,1,5],fallback:["Apporter le planning ; demander au rendez-vous","Choisir de me protéger ou demander du soutien","Attendre une occasion plus sûre de clarifier"],observation:["Question envoyée ; sujet connu ou encore inconnu","Faits appris, y compris l’incertitude restante","Le geste sûr que j’ai réellement fait"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Demander quoi préparer pour le rendez-vous",minimum:"Envoyer une question sur la préparation",minutes:2,cueHint:"Quand un message de rendez-vous omet le sujet",placeHint:"À mon bureau, dans le mail reçu",obstacleHint:"Ma responsable ne peut répondre avant notre rendez-vous sûr",fallbackHint:"Apporter le planning ; demander au rendez-vous",observationHint:"Question envoyée ; sujet connu ou encore inconnu"},stopRule:"Ne transforme pas les mauvais traitements en situation à accepter. Protège-toi, pose des limites ou cherche du soutien si nécessaire.",accessibleAlternative:"Écrit, communication assistée ou personne de confiance conviennent. Pas besoin de te concentrer sur ton corps."},result:{question:"As-tu fait le geste choisi à partir des faits ?",observationPrompt:"Qu’as-tu demandé ou fait, et quels faits ont suivi ?"},judgment:{primary:{id:"calm-4-decision",scenario:"Une responsable avec qui Camille est en sécurité écrit « On peut parler demain ? ». Elle peut répondre aujourd’hui. Camille a dix minutes et le travail actuel à rendre, mais ignore le sujet.",question:"Quel geste vérifie la prédiction ?",options:[{id:"calm-4-positive-story",text:"Lister les raisons pour lesquelles sa responsable pourrait apprécier son travail, puis préparer une discussion positive pour demain.",feedback:"Une explication positive reste possible, mais elle suppose encore une intention. Camille peut laisser la suite incertaine et demander quoi préparer, sans décider qu’une histoire rassurante est vraie."},{id:"calm-4-clarify",text:"Noter le message exact, demander quoi préparer et utiliser la réponse pour choisir un geste concret.",feedback:"Ce choix distingue les faits de la prédiction et recueille une information utile. La réponse peut laisser du doute. Camille gagne pourtant un geste plus clair, sans devoir se sentir rassurée ou supposer une intention."},{id:"calm-4-review-everything",text:"Vérifier le travail à rendre pendant dix minutes et l’apporter demain, sans demander le sujet du rendez-vous.",feedback:"Une vérification limitée peut améliorer le travail. Ici, elle risque de porter sur le mauvais document : le sujet reste inconnu et la responsable peut le préciser. L’inquiétude ne prouve pas une erreur."}],bestOptionId:"calm-4-clarify"}},carry:{takeaway:"Tu peux dire « je ne sais pas encore » et choisir quand même un geste utile.",followUp:{questionId:"calm-4-return",question:"Ton geste a-t-il apporté des faits, ou remplacé une supposition par une autre ?",observationPrompt:"Que s’est-il passé quand ton déclencheur s’est présenté ?",adjustmentPrompt:"Que veux-tu reprendre, changer ou faire avec de l’aide ?"}},goDeeper:{sections:[{heading:"L’équilibre ne demande pas une certitude rassurante",paragraphs:["Pour revoir une pensée, le NHS propose de la repérer, d’examiner les faits et d’envisager une autre lecture équilibrée [C10]. Observation : « Le message propose de parler demain. » Prédiction : « Je vais perdre mon poste. » Autre possibilité : « Il y a peut-être un problème de planning. » Cette possibilité le reste jusqu’à l’arrivée de faits. Tu n’as pas à croire l’explication la plus favorable pour poser une question pratique dans une situation sûre.","Associer fait, prédiction et demande de précision est une adaptation d’ODA, pas un traitement TCC autonome validé. Une erreur connue peut nécessiter une correction. Une demande excessive documentée peut justifier négociation ou soutien. La violence et la contrainte demandent une protection, pas une lecture plus généreuse des intentions de l’autre. Les conseils du NHS distinguent le travail progressif sur des situations redoutées mais sûres du recours aux soins quand l’anxiété perturbe la vie [C03]. Cette leçon n’est pas une thérapie d’exposition."]},{heading:"Un ressenti différent ne change pas les faits",paragraphs:["Webb et ses collègues ont regroupé 306 comparaisons expérimentales [C09]. Changer de perspective ou réinterpréter la situation avait des effets moyens sur les émotions, surtout dans des tâches courtes de laboratoire. L’estimation regroupée pour la suppression des pensées était −0,12. Cela ne prouve pas que chaque tentative de mettre une pensée de côté échoue, ni que retenir son expression soit la même chose. Se sentir moins anxieux ne prouve pas non plus qu’une nouvelle interprétation soit vraie.","Le résumé consulté ne donnait pas d’intervalles de confiance et ne permettait pas de vérifier l’effectif total. Les effets durables de cette fiche courte d’ODA ne sont pas testés. Son but pratique : cesser de prendre une prédiction pour une observation, puis choisir un geste sûr et pertinent pour tes essais. Note ensemble le geste et sa suite réelle. Une question sans réponse laisse de l’incertitude. Cela reste une information utile pour le prochain essai ou pour décider de chercher du soutien."]}],sourceIds:["C03","C09","C10"]}},{schemaVersion:2,revision:2,id:"calm-5",courseId:"calm",locale:"fr",title:"Ta semaine pèse ? Demande de l’aide",goal:"Revois tes essais : reprends un geste utile ou demande le soutien nécessaire.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Tu portes tout sans aide ? Relis tes notes pour choisir la suite ou demander du soutien.",reason:{id:"calm-5-reason",label:"Qu’est-ce qui demande de l’aide plutôt qu’une technique supplémentaire ?",kind:"text",maxLength:160,optional:!0,suggestions:["Organiser un rendez-vous de soins","Gérer les rendez-vous malgré un sommeil perturbé","Une charge que je ne peux porter seul"]},why:{id:"calm-5-why",label:"Que protège ce geste dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Consulte si faire face devient difficile ou si tes démarches ne suffisent pas. Pas besoin d’une crise, d’explication parfaite ni de finir le cours. Lister tes soutiens, c’est préparer. Demander une aide précise, c’est prendre contact.","Relis tes notes : garde un geste faisable ou demande de l’aide. Pas d’essai ? Choisis une occasion sûre. « Tu peux m’aider à prendre rendez-vous ? » est concret. Sans réponse, tu as quand même essayé. Crises de panique répétées ou quotidien perturbé : consulte. Le soutien n’attend pas la pratique."],example:{title:"Camille demande de l’aide pour sa charge",text:"Camille a posé trois questions claires sur les priorités. Elle dort mal et peine à gérer ses rendez-vous de soins. Elle demande à sa sœur : « Tu peux m’aider à appeler le centre de santé aujourd’hui ? » Elle sollicite une consultation. Sa sœur peut aider demain seulement. Camille note les deux contacts, garde une question sur la charge pour la semaine suivante, sans nouvel exercice."}},move:{invitation:"Garde ton plan ; adapte ce contact médical.",instructions:["Relis tes notes : reprends ce qui convenait ou demande le soutien nécessaire.","Avant d’enregistrer, précise destinataire, demande, moment disponible et autre contact."],prompts:[],suggestions:{action:["Appeler le secrétariat du centre de santé public","Demander à ma sœur d’aider à réserver","Demander dix minutes d’échange à un ami"],minimum:["Demander une consultation : sommeil et rendez-vous difficiles","Demander à ma sœur d’organiser le rendez-vous","Envoyer une demande d’échange de dix minutes"],cue:["Après déjeuner, pendant les heures du secrétariat","Après déjeuner aujourd’hui","À l’ouverture du secrétariat du centre de santé"],place:["Chez moi, avec mon téléphone","À la table de cuisine, par messagerie accessible","En privé, avec des moyens de contact accessibles"],minutes:[2,5,10],fallback:["Utiliser le formulaire accessible de demande de rendez-vous","Solliciter ma sœur pour appeler le centre","Appeler à la prochaine ouverture du centre"],observation:["Contact tenté ; réponse et prochaine démarche","Une aide pratique a-t-elle eu lieu ?","Prochaine démarche, même sans réponse"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Appeler le secrétariat du centre de santé public",minimum:"Demander une consultation : sommeil et rendez-vous difficiles",minutes:2,cueHint:"Après déjeuner, pendant les heures du secrétariat",placeHint:"Chez moi, avec mon téléphone",obstacleHint:"Le secrétariat du centre de santé ne répond pas",fallbackHint:"Utiliser le formulaire accessible de demande de rendez-vous",observationHint:"Contact tenté ; réponse et prochaine démarche",kind:"support"},stopRule:"Des pensées de te faire du mal demandent rapidement une aide professionnelle ou de crise. Si tu ne peux rester en sécurité ou es en danger immédiat, contacte les secours locaux.",accessibleAlternative:"Choisis « Adapter ce geste », puis « Soutien ». Service public, écrit, téléphone ou contact accompagné conviennent. Précise destinataire, demande, ouverture et autre contact disponible avant d’enregistrer."},result:{question:"As-tu fait la demande ou le geste choisi ?",observationPrompt:"Qu’as-tu demandé ou fait, et quel soutien as-tu reçu ?"},judgment:{primary:{id:"calm-5-decision",scenario:"L’anxiété de Camille perturbe régulièrement sommeil et rendez-vous. Elle reste en sécurité. Le secrétariat accessible de son centre de santé public est ouvert. Une ligne de soutien propose des orientations ; sa sœur peut aider demain.",question:"Quel plan correspond à ce qu’elle a observé ?",options:[{id:"calm-5-support-and-care",text:"Contacter le centre aujourd’hui, décrire brièvement les répercussions, puis demander l’aide pratique nécessaire.",feedback:"Ce choix utilise une voie accessible vers une évaluation, sans attendre une crise ou une certitude parfaite. Sa sœur peut aider plus tard. Si sa sécurité immédiate change, le recours urgent devient nécessaire."},{id:"calm-5-friends-first",text:"Demander à sa sœur de l’aider à prendre rendez-vous demain et noter les répercussions sur son quotidien.",feedback:"Une aide peut faciliter la prise de rendez-vous. Ici, Camille peut contacter son centre elle-même aujourd’hui. Attendre demain retarde une évaluation accessible. Sa sœur pourra toujours aider par la suite."},{id:"calm-5-complete-explanation",text:"Appeler aujourd’hui la ligne publique de soutien pour trouver un professionnel, puis choisir quel secrétariat contacter.",feedback:"Une orientation aide quand aucun professionnel accessible n’est connu. Son centre est joignable maintenant : chercher ajoute une étape sans répondre au besoin d’accès immédiat. Les deux voies restent des possibilités légitimes."}],bestOptionId:"calm-5-support-and-care"}},carry:{takeaway:"Garde ce qui convient. Demande l’aide que le problème restant exige.",followUp:{questionId:"calm-5-return",question:"Quelle suite a eu ton geste ou ta demande ? Quelle réponse ou démarche reste en attente ?",observationPrompt:"Que s’est-il passé quand ton déclencheur s’est présenté ?",adjustmentPrompt:"Que veux-tu reprendre, changer ou faire avec de l’aide ?"}},goDeeper:{sections:[{heading:"Une demande précise s’adresse à quelqu’un",paragraphs:["L’OMS et le NHS recommandent des liens de confiance et des moyens pratiques pour faire face [C01, C02]. Ce cours en fait une demande précise et facultative : parler, aider pour une tâche ou contacter des soins. La formulation et l’autre contact possible sont conçus par ODA, sans validation comme intervention isolée. Envoyer une demande est observable. Recevoir du soutien, se sentir mieux et résoudre la cause du stress sont des résultats différents.","Relis tes plans et essais plutôt que d’ajouter une habitude. Repère le geste utilisable, ce qui l’a gêné et ce qui dépasse encore tes capacités. Un plan jamais essayé n’a pas de résultat connu : choisis une première occasion sûre ou du soutien. Quelqu’un peut être indisponible ou refuser. Cela aide à choisir un autre contact ou un service public. Tu n’as pas besoin d’un réseau personnel de confiance pour demander une aide professionnelle. Garde les détails sensibles pour toi si tu préfères, tout en prévoyant une prochaine démarche concrète."]},{heading:"Consulter avant que la situation devienne urgente",paragraphs:["Le NHS conseille de chercher une aide professionnelle quand faire face devient difficile ou que les démarches personnelles ne suffisent pas [C02]. Des crises de panique répétées nécessitent une évaluation : les symptômes peuvent avoir d’autres causes et le choix du traitement demander un accompagnement clinique [C04]. Un symptôme physique nouveau ne doit pas être automatiquement attribué au stress. Ce cours ne prescrit ni changement de médicament, ni nombre fixe de séances de TCC, ni programme thérapeutique combinant sommeil, mouvement et respiration.","Même sans danger immédiat, des pensées de te faire du mal demandent rapidement un soutien professionnel ou de crise. Si tu ne peux rester en sécurité ou es en danger immédiat, contacte les secours locaux maintenant. Si c’est sans danger, demande à une personne de confiance de rester. Ces voies protègent ; elles ne constituent ni diagnostic ni algorithme de triage validé. Pour finir, tu peux garder un geste faisable, te reposer, suspendre tes essais ou demander des soins. Aucune option n’exige d’avoir terminé toutes les techniques."]}],sourceIds:["C01","C02","C04"]}}],t=[{practice:["Repère un signal corporel familier ou une situation extérieure. Un symptôme physique ne révèle pas sa cause.","Nomme l’émotion en un mot ; le mot n’a pas à être parfait.","Décris la situation en une phrase : « Dans cette situation, je ressens… »."],reflection:"Quel signe te fait le plus souvent remarquer ton stress ?",question:"Quelle façon de voir le stress correspond à cette leçon ?",options:["Si je ressens du stress, quelque chose va forcément très mal. Je dois m’en débarrasser immédiatement.","Le stress est une réaction ordinaire aux difficultés ; le repérer et le nommer peut être un premier pas.","Nommer mon émotion ne fera que l’amplifier, donc je dois l’ignorer."],correct:1,feedback:"Le stress peut accompagner les difficultés. Le repérer et le nommer peut aider à choisir un geste utile, sans garantir de soulagement. Des symptômes nouveaux ou des difficultés à faire face peuvent nécessiter un avis médical ou du soutien."},{practice:["Si cela convient, assieds-toi en sécurité et essaie volontairement les cinq minutes étudiées. Respiration ordinaire et repère extérieur sont d’autres possibilités.","Pour le soupir cyclique, inspire lentement, ajoute une inspiration plus courte sans forcer, puis expire lentement. Arrête en cas de vertiges ou de malaise.","Note séparément le confort, la pratique ou l’arrêt, et l’humeur. Symptômes nouveaux ou inquiétants : avis médical. Ne conduis pas avec des symptômes."],reflection:"Qu’as-tu remarqué dans ton corps en allongeant l’expiration ?",question:"Sur quoi le soupir cyclique met-il l’accent ?",options:["Retenir son souffle le plus longtemps possible.","Enchaîner des respirations rapides et profondes.","Garder une expiration lente et longue."],correct:2,feedback:"Le soupir cyclique associe deux inspirations à une expiration lente. L’étude testait cinq minutes par jour pendant 28 jours, pas un effet immédiat. Arrête en cas de vertiges ou de malaise et respire normalement."},{practice:["Choisis aujourd’hui un mouvement adapté, y compris assis et accessible. Si bouger ne convient pas, garde une pause immobile.","Associe-le à un moment habituel de ta journée, par exemple une courte marche après déjeuner.","Si c’est utile, note ta tension avant et après. Des sensations inchangées comptent aussi ; un changement ne prouve pas sa cause."],reflection:"Quel mouvement te donne une pause plutôt qu’une punition ?",question:"Comment lire la synthèse de revues de Singh et ses collègues, publiée en 2023 ?",options:["Le mouvement est associé à moins de symptômes, mais la plupart des revues étaient de faible qualité.","Toute personne qui fait de l’exercice perdra forcément son anxiété.","Si je fais de l’exercice, je n’ai plus besoin de médicament ou de thérapie."],correct:0,feedback:"Les programmes d’activité réduisaient les symptômes en moyenne, mais la plupart des revues étaient de qualité extrêmement faible. Leurs résultats médians ne prédisent pas une pause brève et ne remplacent pas les soins nécessaires."},{practice:["Décris en une phrase une situation qui te stresse ces derniers temps.","Envisage d’autres explications plausibles sans inventer les intentions. Une explication incertaine peut être plus juste qu’une positive.","Imagine le regard d’une personne neutre sur la situation. Puis dis-toi la phrase que tu dirais à un ami dans le même cas."],reflection:"En regardant la situation autrement, qu’est-ce qui a changé et qu’est-ce qui reste pareil ?",question:"Dans la méta-analyse de Webb et ses collègues de 2012, quelle stratégie était plus efficace ?",options:["Essayer de ne plus penser du tout à l’événement.","Essayer de voir la situation avec le regard d’un observateur extérieur.","Rester bloqué sur l’émotion négative et la ressasser."],correct:1,feedback:"Changer de perspective et réinterpréter influençaient en moyenne des émotions brèves de laboratoire. L’estimation regroupée de suppression des pensées était négative ; cela ne prouve pas un échec systématique. Appuie-toi sur les faits et choisis un geste sûr."},{practice:["Repère des contacts disponibles, de confiance ou publics. Un réseau personnel n’est pas nécessaire pour demander des soins.","Choisis un moment cette semaine pour dire à quelqu’un comment tu vas ou demander une petite aide.","Avec le tableau d’aide, note en privé vers qui te tourner selon la situation."],reflection:"Lors d’une journée difficile, qui aimerais-tu contacter en premier ?",question:"Si tu ne peux rester en sécurité ou es en danger immédiat, que dois-tu faire ?",options:["Terminer les exercices du cours et attendre.","Me débrouiller seul pour ne déranger personne.","Appeler les secours locaux et, si possible, demander à quelqu’un de rester avec moi."],correct:2,feedback:"Contacte les secours locaux si tu ne peux rester en sécurité ou es en danger immédiat. Même sans danger immédiat, des pensées de te faire du mal nécessitent rapidement une aide professionnelle ou de crise. N’attends pas de finir le cours."}],a=[{id:"1758876019128-e76eebf402bd",alt:"Personne fatiguée, la tête appuyée sur une main à table"},{id:"1717691526463-975c4119505c",alt:"Femme debout, les yeux fermés devant un arbre"},{id:"1758272421829-7028296dee8f",alt:"Femme s’étirant au sol dans un salon"},{id:"1658279366796-e0c28623cd27",alt:"Femme assise sur un rebord de fenêtre, regardant dehors"},{id:"1747764925585-6c2df83b3fd2",alt:"Deux femmes discutant autour d’un café"}],r={id:"calm",title:"Le stress dicte tes réponses ?",subtitle:"Cinq leçons pour repérer un signal, essayer un geste sûr et choisir la suite, même si tes émotions varient.",description:"Essaie un geste en réponse à un déclencheur de ta semaine. Ajoute une pause confortable, un mouvement adapté, une vérification des faits ou du soutien seulement si cela aide ton geste.",scope:"Éducation à la gestion du stress quotidien pour adultes, sans diagnostic ni traitement. Arrête les exercices de respiration ou de mouvement en cas de vertiges, de gêne ou de malaise. Assieds-toi en sécurité et respire normalement. Des symptômes physiques nouveaux ou inquiétants nécessitent un avis médical, urgent s’ils sont sévères. Ne les attribue pas d’office à une panique. Consulte en cas de crises répétées, de quotidien perturbé, de difficultés à faire face ou de démarches personnelles insuffisantes. Ne modifie pas seul ton traitement ou tes médicaments. Des pensées de te faire du mal demandent rapidement un soutien professionnel ou de crise. Si tu ne peux rester en sécurité ou es en danger immédiat, contacte les secours locaux. Face à des violences, privilégie la sécurité et un soutien spécialisé, pas un exercice pour tolérer la situation.",outcome:"Un geste sûr quand ton signal de stress apparaît, des notes honnêtes sur tes essais et une suite faisable pour la semaine ou le soutien.",photo:{id:"1557316655-8715fdecd2d1",alt:"Lac calme au pied d’une montagne"},lang:"fr",lessons:n.map((e,s)=>({id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,...t[s],takeaway:e.carry.takeaway,sources:s===0?[...e.goDeeper.sourceIds,"C01"]:e.goDeeper.sourceIds,deeper:e.goDeeper.sections,example:{title:`Exemple inventé : ${e.idea.example.title}`,text:e.idea.example.text},photo:a[s]}))},u=Object.freeze(Object.defineProperty({__proto__:null,COURSE:r,LESSONS_V2:n,SOURCES:i},Symbol.toStringTag,{value:"Module"}));export{u as c};
